import { cn } from "@/lib/cn";

/** Widths generated by scripts/images.mjs. Keep these in sync with that script. */
export const IMAGE_WIDTHS = {
  portrait: [480, 760, 1144],
  desktop: [640, 1024, 1440, 2048],
  mobile: [240, 400, 780],
  poster: [640, 1196],
} as const;

export function srcSet(name: string, widths: readonly number[], ext: "avif" | "webp") {
  return widths.map((w) => `/images/generated/${name}-${w}.${ext} ${w}w`).join(", ");
}

/** "/images/work/forgeworks-desktop.png" → "forgeworks-desktop" */
export function generatedName(src: string) {
  return src
    .split("/")
    .pop()!
    .replace(/\.[a-z]+$/, "");
}

type PictureProps = {
  /** base name in /images/generated, e.g. "forgeworks-desktop" */
  name: string;
  widths: readonly number[];
  sizes: string;
  fallbackSrc: string;
  alt: string;
  width: number;
  height: number;
  priority?: boolean;
  className?: string;
  imgClassName?: string;
};

export function Picture({
  name,
  widths,
  sizes,
  fallbackSrc,
  alt,
  width,
  height,
  priority = false,
  className,
  imgClassName,
}: PictureProps) {
  return (
    <picture className={cn("block", className)}>
      <source type="image/avif" srcSet={srcSet(name, widths, "avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(name, widths, "webp")} sizes={sizes} />
      <img
        src={fallbackSrc}
        alt={alt}
        width={width}
        height={height}
        sizes={sizes}
        loading={priority ? "eager" : "lazy"}
        decoding="async"
        fetchPriority={priority ? "high" : "auto"}
        className={imgClassName}
      />
    </picture>
  );
}
